    // Rocks
    public static final Map<RockType, DeferredBlock<CustomBlock>> ROCK_BLOCKS = Arrays.stream(RockType.values()).map(type -> Pair.of(type, ROCK_BLOCK_REGISTRY.register(type.getName(), () -> new CustomBlock(Block.Properties.of().sound(SoundType.STONE).mapColor(type.getColor()).strength(1.5F, 6.0F).requiresCorrectToolForDrops().requiresCorrectToolForDrops(), ToolTypes.PICKAXE)))).collect(Collectors.toMap(Pair::getKey, Pair::getValue));

